class Solution {
    public int[] asteroidCollision(int[] asteroids) {
        Deque<Integer> stack = new ArrayDeque<>();

        for (int asteroid : asteroids) {
            boolean survived = true;

            // 只有正数在栈顶且当前为负数时才会碰撞
            while (survived && !stack.isEmpty() && 
                   stack.peek() > 0 && asteroid < 0) {

                int top = stack.peek();

                if (top < -asteroid) {
                    // 栈顶小，被摧毁，继续比较
                    stack.pop();
                } else if (top == -asteroid) {
                    // 相等，两者都销毁
                    stack.pop();
                    survived = false;
                } else {
                    // 栈顶大，当前小行星被摧毁
                    survived = false;
                }
            }

            if (survived) {
                stack.push(asteroid);
            }
        }

        // 转换为数组（需要反转顺序）
        int[] result = new int[stack.size()];
        for (int i = result.length - 1; i >= 0; i--) {
            result[i] = stack.pop();
        }

        return result;
    }
}

class Solution {
    public int[] asteroidCollision(int[] asteroids) {
        List<Integer> list = new ArrayList<>();

        for (int asteroid : asteroids) {
            boolean survived = true;

            while (survived && !list.isEmpty() && 
                   list.get(list.size() - 1) > 0 && asteroid < 0) {

                int top = list.get(list.size() - 1);

                if (top < -asteroid) {
                    list.remove(list.size() - 1);
                } else if (top == -asteroid) {
                    list.remove(list.size() - 1);
                    survived = false;
                } else {
                    survived = false;
                }
            }

            if (survived) {
                list.add(asteroid);
            }
        }

        return list.stream().mapToInt(i -> i).toArray();
    }
}
